    def _require_device_tools(self) -> FortiPamReadOnlyTools:
        if self._device_tools is None:
            self._ensure_runtime_environment()
            try:
                config = load_config()
            except ConfigurationError as exc:
                raise RuntimeError("FortiPAM live tools are not configured.") from exc
            self._device_tools = FortiPamReadOnlyTools(config)
        return self._device_tools

    def _require_cli_tools(self) -> FortiPamCliTools:
        if self._cli_tools is None:
            self._ensure_runtime_environment()
            try:
                config = load_cli_config()
            except ConfigurationError as exc:
                raise RuntimeError("FortiPAM CLI tools are not configured.") from exc
            self._cli_tools = FortiPamCliTools(config)
        return self._cli_tools

    def _require_diagnostic_service(self) -> FortiPamDiagnosticService:
        if self._diagnostic_settings is None:
            raise DiagnosticServiceError(DIAGNOSTIC_UNAVAILABLE)
        if self._diagnostic_service is None:
            async def collect_api() -> dict[str, object]:
                return await self._require_device_tools().get_ha_configuration_posture_summary()

            async def collect_cli() -> dict[str, object]:
                return await self._require_cli_tools().get_ha_configuration_summary()

            ha_reconciliation = self._v4_ha_reconciliation
            if self._v4_ha_reconciliation_enabled and ha_reconciliation is None:
                prerequisite_provider = (
                    self._v4_ha_reconciliation_prerequisite_provider
                )
                query_permission_provider = (
                    self._v4_ha_reconciliation_query_permission_provider
                )
                if prerequisite_provider is None or query_permission_provider is None:
                    raise DiagnosticServiceError(DIAGNOSTIC_UNAVAILABLE)

                async def collect_cli_status() -> dict[str, object]:
                    return await self._require_cli_tools().get_ha_status_summary()

                async def collect_cli_checksum() -> dict[str, object]:
                    return await self._require_cli_tools().get_ha_checksum_summary()

                ha_reconciliation = HaReconciliationRuntimeBinding(
                    BoundHaReconciliation(
                        api_configuration_collector=collect_api,
                        cli_configuration_collector=collect_cli,
                        cli_status_collector=collect_cli_status,
                        cli_checksum_collector=collect_cli_checksum,
                        prerequisite_provider=prerequisite_provider,
                    ),
                    query_permission_provider,
                )

            self._diagnostic_service = FortiPamDiagnosticService(
                self._diagnostic_settings,
                ha_api_collector=collect_api,
                ha_cli_collector=collect_cli,
                ha_reconciliation=ha_reconciliation,
            )
        return self._diagnostic_service

    def _v4_planning_principal(self) -> Any:
        if self._runtime_profile not in V4_HTTP_PROFILES:
            raise RuntimeError("FortiPAM V4 planning is unavailable.")
        if self._v4_planning_authorization is None:
            raise RuntimeError("FortiPAM V4 planning authorization is unavailable.")
        from .v4_plan_runtime import planning_principal_from_access_token

        return planning_principal_from_access_token(
            self._access_token(),
            self._v4_planning_authorization,
        )

